package observability

import (
    "log/slog"
    "net/http"
    "time"
)

type captureWriter struct { http.ResponseWriter; status int }
func (w *captureWriter) WriteHeader(code int) {
    if w.status != 0 { return }
    w.status = code
    w.ResponseWriter.WriteHeader(code)
}
func (w *captureWriter) Write(p []byte) (int, error) {
    if w.status == 0 { w.WriteHeader(http.StatusOK) }
    return w.ResponseWriter.Write(p)
}

func Logging(logger *slog.Logger, routeName func(*http.Request) string) func(http.Handler) http.Handler {
    return func(next http.Handler) http.Handler {
        return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
            started := time.Now()
            cw := &captureWriter{ResponseWriter: w}
            next.ServeHTTP(cw, r)
            status := cw.status
            if status == 0 { status = http.StatusOK }
            logger.InfoContext(r.Context(), "http request",
                slog.String("method", r.Method), slog.String("route", routeName(r)),
                slog.Int("status", status), slog.Duration("duration", time.Since(started)))
        })
    }
}

