package health

import (
    "context"
    "errors"
    "fmt"
    "sort"
    "time"
    "golang.org/x/sync/errgroup"
)

type Check func(context.Context) error
func Ready(ctx context.Context, checks map[string]Check, timeout time.Duration) error {
    ctx, cancel := context.WithTimeout(ctx, timeout)
    defer cancel()
    group, ctx := errgroup.WithContext(ctx)
    failed := make(chan string, len(checks))
    for name, check := range checks {
        name, check := name, check
        group.Go(func() error { if err := check(ctx); err != nil { failed <- name; return err }; return nil })
    }
    err := group.Wait()
    close(failed)
    if err == nil { return nil }
    names := make([]string, 0, len(failed))
    for name := range failed { names = append(names, name) }
    sort.Strings(names)
    return fmt.Errorf("readiness failed for %v: %w", names, errors.Join(err, ctx.Err()))
}
